import {query} from '../client.js';
function required(value,name){if(!value||value===true)throw new Error('Provide --'+name);return value;}
function boolean(value,name){if(value===true||value==='true')return true;if(value===false||value==='false')return false;throw new Error('--'+name+' must be true or false');}
function ids(value){return String(required(value,'ids')).split(',').map(id=>id.trim()).filter(Boolean);}
async function list(client,path,filters,all){
  let result=await client.get(path+query(filters));
  if(!all)return result;
  const items=[...result.items],seen=new Set();
  while(result.nextCursor){
    if(seen.has(result.nextCursor))throw new Error('Server repeated a pagination cursor');
    seen.add(result.nextCursor);result=await client.get(path+query({...filters,cursor:result.nextCursor}));items.push(...result.items);
  }
  return {...result,items,nextCursor:null};
}
export async function feedCommand({args,options,client,print}) {
  const [action='list',type,target]=args;
  if(action==='watch'||action==='unwatch'){
    if(!['issue','project'].includes(type)||!target)throw new Error('Usage: crew feed '+action+' issue|project ID');
    return print(action==='watch'?await client.post('/subscriptions',{targetType:type,targetId:target}):await client.delete('/subscriptions/'+type+'/'+encodeURIComponent(target)));
  }
  const orgId=required(options.org,'org');
  if(action==='subscriptions')return print(await list(client,'/subscriptions',{orgId,projectId:options.project,limit:options.limit,cursor:options.cursor},options.all));
  if(action!=='list')throw new Error('Unknown feed action. Use crew feed --help');
  return print(await list(client,'/activity',{orgId,projectId:options.project,issueId:options.issue,userId:options.user,entityType:options.entity,action:options.action,from:options.from,to:options.to,limit:options.limit,cursor:options.cursor},options.all));
}
feedCommand.help=`crew feed list --org ID [--project ID] [--issue ID] [--user ACTOR] [--entity TYPE] [--action ACTION] [--from ISO] [--to ISO] [--limit N] [--cursor CURSOR] [--all]
crew feed subscriptions --org ID [--project ID] [--limit N] [--cursor CURSOR] [--all]
crew feed watch issue|project ID
crew feed unwatch issue|project ID
Watch actions apply only to your account. Unwatch mutes ordinary automatic subscriptions; explicit mentions still notify. --all traverses every accessible page.`;
export async function inboxCommand({args,options,client,print}) {
  const [action='list',id]=args;
  if(action==='read'||action==='unread'){
    if(!id)throw new Error('Usage: crew inbox '+action+' NOTIFICATION');
    return print(await client.patch('/notifications/'+encodeURIComponent(id),{read:action==='read'}));
  }
  const orgId=required(options.org,'org');
  if(action==='list')return print(await list(client,'/notifications',{orgId,projectId:options.project,state:options.state,limit:options.limit,cursor:options.cursor},options.all));
  if(action==='mark'||action==='mark-all'){
    const read=options.read===undefined?true:boolean(options.read,'read');
    if(action==='mark-all'&&!options.yes)throw new Error('Marking every accessible notification requires --yes');
    return print(await client.post('/notifications/mark',{orgId,read,...(action==='mark-all'?{all:true}:{ids:ids(options.ids)})}));
  }
  if(action==='preferences'){
    const body={orgId};
    if(options.frequency!==undefined){
      if(!['manual','15-minute','hourly','daily'].includes(options.frequency))throw new Error('--frequency must be manual, 15-minute, hourly or daily');
      body.digestFrequency=options.frequency;
    }
    if(options.email!==undefined)body.emailEnabled=boolean(options.email,'email');
    if(options['mentions-only']!==undefined)body.mentionsOnly=boolean(options['mentions-only'],'mentions-only');
    return print(Object.keys(body).length>1?await client.patch('/notification-preferences',body):await client.get('/notification-preferences'+query({orgId})));
  }
  if(action==='schedule'){
    const result=await client.get('/notification-preferences'+query({orgId}));
    return print(result.preferences.digestSchedule);
  }
  if(action==='digest')return print(await client.post('/digests',{orgId}));
  if(action==='digests')return print(await list(client,'/digests',{orgId,limit:options.limit,cursor:options.cursor},options.all));
  throw new Error('Unknown inbox action. Use crew inbox --help');
}
inboxCommand.help=`crew inbox list --org ID [--project ID] [--state all|unread|read] [--limit N] [--cursor CURSOR] [--all]
crew inbox read|unread NOTIFICATION
crew inbox mark --org ID --ids ID,ID [--read true|false]
crew inbox mark-all --org ID --yes [--read true|false]
crew inbox preferences --org ID [--email true|false] [--mentions-only true|false] [--frequency manual|15-minute|hourly|daily]
crew inbox schedule --org ID
crew inbox digest --org ID
crew inbox digests --org ID [--limit N] [--cursor CURSOR] [--all]
Digests batch up to 200 newly unread visible notifications once into the shared local outbox. Manual is the default. A selected cadence drains remaining batches sequentially; schedule shows next/last run, status and remaining backlog. Errors suspend automatic batching until a deliberate cadence/settings save. No external email is sent.`;

import {digestStatusLabel,digestTimeLabel} from './digest-state.js';
import {useScopedLoad} from './scoped-load.js';
import {useState} from 'preact/hooks';
import {Button,Notice,Empty,Loading} from '../../components/ui.jsx';
import {queryString} from '../../api.js';
import {useScopedAction} from './use-action.js';
export function DigestPanel({api,orgId}) {
  const [cursor,setCursor]=useState('');
  const [history,setHistory]=useState([]);
  const action=useScopedAction(orgId);
  const load=useScopedLoad(orgId+(typeof cursor==='undefined'?'':cursor),()=>api.get('/digests?'+queryString({orgId,cursor,limit:10})),[orgId,cursor]);
  function batch(){
    action.run(signal=>api.post('/digests',{orgId},{signal}),result=>{
      setCursor('');setHistory([]);load.reload();
      return result.count?'Queued '+result.count+' updates. '+result.remaining+' remain available for another deliberate batch.':'No new unread updates need a digest.';
    });
  }
  return <section>
    <h2>Email digests</h2>
    <p>Queue up to 200 new unread updates in your private local outbox. Batching preserves unread state. Invitation and reset messages never appear in this view.</p>
    <Button busy={action.busy} type="button" onClick={batch}>Queue unread digest</Button>
    <Notice error={action.error??load.error}/><Notice>{action.message}</Notice>
    {load.loading?<Loading/>:!load.data?.items.length?<Empty>No digests queued yet.</Empty>:load.data.items.map(digest=><details key={digest.id}>
      <summary>{new Date(digest.createdAt).toLocaleString()} · {digest.count} accessible updates</summary>
      <pre>{digest.textBody||'These updates are no longer accessible.'}</pre>
    </details>)}
    <div className="pagination">
      <Button type="button" disabled={!history.length||load.loading} onClick={()=>{setCursor(history.at(-1));setHistory(history.slice(0,-1));}}>Previous digests</Button>
      <Button type="button" disabled={!load.data?.nextCursor||load.loading} onClick={()=>{setHistory([...history,cursor]);setCursor(load.data.nextCursor);}}>Next digests</Button>
    </div>
  </section>;
}
export function ScheduleStatus({schedule}) {
  if(!schedule)return null;
  return <div data-testid="digest-schedule"><dl>
    <dt>Status</dt><dd data-testid="digest-status">{digestStatusLabel(schedule)}</dd>
    <dt>Next run</dt><dd data-testid="digest-next">{digestTimeLabel(schedule.nextRunAt)}</dd>
    <dt>Last run</dt><dd data-testid="digest-last">{digestTimeLabel(schedule.lastRunAt)}</dd>
    <dt>Remaining at last batch</dt><dd>{schedule.remaining}</dd>
  </dl><Notice error={schedule.lastError}/></div>;
}
export function Preferences({api,orgId}) {
  const load=useScopedLoad(orgId,()=>api.get('/notification-preferences?'+queryString({orgId})),[orgId]);
  const action=useScopedAction(orgId);
  function update(key,value){action.run(signal=>api.patch('/notification-preferences',{orgId,[key]:value},{signal}),()=>{load.reload();return 'Preferences saved.';});}
  return <section>
    <h2>Notification preferences</h2><p>Manual batching is the default. A cadence opts this organization into automatic local outbox batching. No external email is sent.</p><Notice error={action.error??load.error}/><Notice>{action.message}</Notice>
    {load.loading?<Loading/>:load.data&&<div>
      <label><input type="checkbox" disabled={action.busy} checked={load.data.preferences.mentionsOnly} onChange={event=>update('mentionsOnly',event.currentTarget.checked)}/> Notify me only for explicit mentions</label>
      <label><input data-testid="digest-email" type="checkbox" disabled={action.busy} checked={load.data.preferences.emailEnabled} onChange={event=>update('emailEnabled',event.currentTarget.checked)}/> Enable email digest batching</label>
      <label>Batching cadence <select data-testid="digest-frequency" disabled={action.busy} value={load.data.preferences.digestFrequency} onChange={event=>update('digestFrequency',event.currentTarget.value)}>
        <option value="manual">Manual only</option><option value="15-minute">Every 15 minutes</option><option value="hourly">Hourly</option><option value="daily">Daily</option>
      </select></label>
      <ScheduleStatus schedule={load.data.preferences.digestSchedule}/>
      <Button type="button" disabled={action.busy} onClick={()=>load.reload()}>Refresh digest schedule</Button>
    </div>}
  </section>;
}

const labels={manual:'Manual batching',disabled:'Email batching disabled',scheduled:'Scheduled',backlog:'Draining remaining backlog',idle:'Waiting for new updates',error:'Automatic batching suspended','access-lost':'Access lost; save settings after restoring access'};
export function digestStatusLabel(schedule) {
  return labels[schedule?.status]??'Schedule unavailable';
}
export function digestTimeLabel(value) {
  if(!value)return 'None';
  const time=Date.parse(value);
  return Number.isFinite(time)?new Date(time).toLocaleString()+' ('+value+')':'Unavailable';
}
